  "code": "struct Quaternion {\n  float x;float y;float z;float w;\n};\n#ifndef GPU_METAL\nQuaternion Quaternion_ctor_();\nQuaternion Quaternion_identity();\nfloat4 _as_float4(const Quaternion this_);\n#endif\n                          Quaternion Quaternion_ctor_() {Quaternion r;r.x=0.0f;r.y=0.0f;r.z=0.0f;r.w=0.0f;return r;}\n         Quaternion Quaternion_identity()\n  {\n    return _ctor(Quaternion) 1.0f, 0.0f, 0.0f, 0.0f _rotc() ;\n  }\n  float4 _as_float4(const Quaternion this_)\n  {\n    return float4(this_.x, this_.y, this_.z, this_.w);\n  }\nQuaternion math_quaternion_multiply(Quaternion a, Quaternion b)\n{\n  Quaternion result;\n  result.x = a.x * b.x - a.y * b.y - a.z * b.z - a.w * b.w;\n  result.y = a.x * b.y + a.y * b.x + a.z * b.w - a.w * b.z;\n  result.z = a.x * b.z - a.y * b.w + a.z * b.x + a.w * b.y;\n  result.w = a.x * b.w + a.y * b.z - a.z * b.y + a.w * b.x;\n  return result;\n}\n\nQuaternion quaternion_conjugate(Quaternion q)\n{\n  return _ctor(Quaternion) q.x, -q.y, -q.z, -q.w _rotc() ;\n}\n\nfloat3 transform_point_by_quaternion(Quaternion q, float3 v)\n{\n  Quaternion v_quat = _ctor(Quaternion) 0.0f, v.x, v.y, v.z _rotc() ;\n  Quaternion result = math_quaternion_multiply(math_quaternion_multiply(q, v_quat),\n                                                     quaternion_conjugate(q));\n  return float3(result.y, result.z, result.w);\n}"
