  "code": "void node_mix_blend(float fac, float4 col1, float4 col2, _ref(float4 ,outcol))\n{\n  outcol = mix(col1, col2, fac);\n}\nvoid node_mix_add(float fac, float4 col1, float4 col2, _ref(float4 ,outcol))\n{\n\n  outcol = mix(col1, col1 + col2, fac);\n  outcol.a = col1.a;\n}\nvoid node_mix_mult(float fac, float4 col1, float4 col2, _ref(float4 ,outcol))\n{\n\n  outcol = mix(col1, col1 * col2, fac);\n  outcol.a = col1.a;\n}\nvoid node_mix_screen(float fac, float4 col1, float4 col2, _ref(float4 ,outcol))\n{\n\n  float facm = 1.0f - fac;\n\n  outcol = float4(1.0f) - (float4(facm) + fac * (float4(1.0f) - col2)) * (float4(1.0f) - col1);\n  outcol.a = col1.a;\n}\nvoid node_mix_overlay(float fac, float4 col1, float4 col2, _ref(float4 ,outcol))\n{\n\n  float facm = 1.0f - fac;\n\n  outcol = col1;\n\n  if (outcol.r < 0.5f) {\n    outcol.r *= facm + 2.0f * fac * col2.r;\n  }\n  else {\n    outcol.r = 1.0f - (facm + 2.0f * fac * (1.0f - col2.r)) * (1.0f - outcol.r);\n  }\n\n  if (outcol.g < 0.5f) {\n    outcol.g *= facm + 2.0f * fac * col2.g;\n  }\n  else {\n    outcol.g = 1.0f - (facm + 2.0f * fac * (1.0f - col2.g)) * (1.0f - outcol.g);\n  }\n\n  if (outcol.b < 0.5f) {\n    outcol.b *= facm + 2.0f * fac * col2.b;\n  }\n  else {\n    outcol.b = 1.0f - (facm + 2.0f * fac * (1.0f - col2.b)) * (1.0f - outcol.b);\n  }\n}\nvoid node_mix_sub(float fac, float4 col1, float4 col2, _ref(float4 ,outcol))\n{\n\n  outcol = mix(col1, col1 - col2, fac);\n  outcol.a = col1.a;\n}\nvoid node_mix_div_fallback(float fac, float4 col1, float4 col2, _ref(float4 ,outcol))\n{\n\n  float facm = 1.0f - fac;\n\n  outcol = col1;\n\n  if (col2.r != 0.0f) {\n    outcol.r = facm * outcol.r + fac * outcol.r / col2.r;\n  }\n  if (col2.g != 0.0f) {\n    outcol.g = facm * outcol.g + fac * outcol.g / col2.g;\n  }\n  if (col2.b != 0.0f) {\n    outcol.b = facm * outcol.b + fac * outcol.b / col2.b;\n  }\n}\nvoid node_mix_diff(float fac, float4 col1, float4 col2, _ref(float4 ,outcol))\n{\n\n  outcol = mix(col1, abs(col1 - col2), fac);\n  outcol.a = col1.a;\n}\nvoid node_mix_exclusion(float fac, float4 col1, float4 col2, _ref(float4 ,outcol))\n{\n\n  outcol = max(mix(col1, col1 + col2 - 2.0f * col1 * col2, fac), 0.0f);\n  outcol.a = col1.a;\n}\nvoid node_mix_dark(float fac, float4 col1, float4 col2, _ref(float4 ,outcol))\n{\n\n  outcol.rgb = mix(col1.rgb, min(col1.rgb, col2.rgb), fac);\n  outcol.a = col1.a;\n}\nvoid node_mix_light(float fac, float4 col1, float4 col2, _ref(float4 ,outcol))\n{\n  outcol.rgb = mix(col1.rgb, max(col1.rgb, col2.rgb), fac);\n  outcol.a = col1.a;\n}\nvoid node_mix_dodge(float fac, float4 col1, float4 col2, _ref(float4 ,outcol))\n{\n  outcol = col1;\n\n  if (outcol.r != 0.0f) {\n    float tmp = 1.0f - fac * col2.r;\n    if (tmp <= 0.0f) {\n      outcol.r = 1.0f;\n    }\n    else if ((tmp = outcol.r / tmp) > 1.0f) {\n      outcol.r = 1.0f;\n    }\n    else {\n      outcol.r = tmp;\n    }\n  }\n  if (outcol.g != 0.0f) {\n    float tmp = 1.0f - fac * col2.g;\n    if (tmp <= 0.0f) {\n      outcol.g = 1.0f;\n    }\n    else if ((tmp = outcol.g / tmp) > 1.0f) {\n      outcol.g = 1.0f;\n    }\n    else {\n      outcol.g = tmp;\n    }\n  }\n  if (outcol.b != 0.0f) {\n    float tmp = 1.0f - fac * col2.b;\n    if (tmp <= 0.0f) {\n      outcol.b = 1.0f;\n    }\n    else if ((tmp = outcol.b / tmp) > 1.0f) {\n      outcol.b = 1.0f;\n    }\n    else {\n      outcol.b = tmp;\n    }\n  }\n}\nvoid node_mix_burn(float fac, float4 col1, float4 col2, _ref(float4 ,outcol))\n{\n\n  float tmp, facm = 1.0f - fac;\n\n  outcol = col1;\n\n  tmp = facm + fac * col2.r;\n  if (tmp <= 0.0f) {\n    outcol.r = 0.0f;\n  }\n  else if ((tmp = (1.0f - (1.0f - outcol.r) / tmp)) < 0.0f) {\n    outcol.r = 0.0f;\n  }\n  else if (tmp > 1.0f) {\n    outcol.r = 1.0f;\n  }\n  else {\n    outcol.r = tmp;\n  }\n\n  tmp = facm + fac * col2.g;\n  if (tmp <= 0.0f) {\n    outcol.g = 0.0f;\n  }\n  else if ((tmp = (1.0f - (1.0f - outcol.g) / tmp)) < 0.0f) {\n    outcol.g = 0.0f;\n  }\n  else if (tmp > 1.0f) {\n    outcol.g = 1.0f;\n  }\n  else {\n    outcol.g = tmp;\n  }\n\n  tmp = facm + fac * col2.b;\n  if (tmp <= 0.0f) {\n    outcol.b = 0.0f;\n  }\n  else if ((tmp = (1.0f - (1.0f - outcol.b) / tmp)) < 0.0f) {\n    outcol.b = 0.0f;\n  }\n  else if (tmp > 1.0f) {\n    outcol.b = 1.0f;\n  }\n  else {\n    outcol.b = tmp;\n  }\n}\nvoid node_mix_hue(float fac, float4 col1, float4 col2, _ref(float4 ,outcol))\n{\n\n  outcol = col1;\n\n  float4 hsv, hsv2, tmp;\n  rgb_to_hsv(col2, hsv2);\n\n  if (hsv2.y != 0.0f) {\n    rgb_to_hsv(outcol, hsv);\n    hsv.x = hsv2.x;\n    hsv_to_rgb(hsv, tmp);\n\n    outcol = mix(outcol, tmp, fac);\n    outcol.a = col1.a;\n  }\n}\nvoid node_mix_sat(float fac, float4 col1, float4 col2, _ref(float4 ,outcol))\n{\n\n  outcol = col1;\n\n  float4 hsv, hsv2;\n  rgb_to_hsv(outcol, hsv);\n\n  if (hsv.y != 0.0f) {\n    rgb_to_hsv(col2, hsv2);\n\n    hsv.y = (1.0f - fac) * hsv.y + fac * hsv2.y;\n    hsv_to_rgb(hsv, outcol);\n  }\n}\nvoid node_mix_val(float fac, float4 col1, float4 col2, _ref(float4 ,outcol))\n{\n\n  float4 hsv, hsv2;\n  rgb_to_hsv(col1, hsv);\n  rgb_to_hsv(col2, hsv2);\n\n  hsv.z = (1.0f - fac) * hsv.z + fac * hsv2.z;\n  hsv_to_rgb(hsv, outcol);\n}\nvoid node_mix_color(float fac, float4 col1, float4 col2, _ref(float4 ,outcol))\n{\n  outcol = col1;\n\n  float4 hsv, hsv2, tmp;\n  rgb_to_hsv(col2, hsv2);\n\n  if (hsv2.y != 0.0f) {\n    rgb_to_hsv(outcol, hsv);\n    hsv.x = hsv2.x;\n    hsv.y = hsv2.y;\n    hsv_to_rgb(hsv, tmp);\n\n    outcol = mix(outcol, tmp, fac);\n    outcol.a = col1.a;\n  }\n}\nvoid node_mix_soft(float fac, float4 col1, float4 col2, _ref(float4 ,outcol))\n{\n\n  float facm = 1.0f - fac;\n\n  float4 one = float4(1.0f);\n  float4 scr = one - (one - col2) * (one - col1);\n  outcol = facm * col1 + fac * ((one - col1) * col2 * col1 + col1 * scr);\n  outcol.a = col1.a;\n}\nvoid node_mix_linear(float fac, float4 col1, float4 col2, _ref(float4 ,outcol))\n{\n\n  outcol = col1 + fac * (2.0f * (col2 - float4(0.5f)));\n  outcol.a = col1.a;\n}\nvoid node_mix_float(float fac, float f1, float f2, _ref(float ,outfloat))\n{\n\n  outfloat = f1 * (1.0f - fac) + f2 * fac;\n}\nvoid node_mix_vector(float fac, float3 v1, float3 v2, _ref(float3 ,outvec))\n{\n\n  outvec = v1 * (1.0f - fac) + v2 * fac;\n}\nvoid node_mix_vector_non_uniform(float3 facvec, float3 v1, float3 v2, _ref(float3 ,outvec))\n{\n\n  outvec = v1 * (float3(1.0f) - facvec) + v2 * facvec;\n}\nvoid node_mix_rgba(float fac, float4 col1, float4 col2, _ref(float4 ,outcol))\n{\n  outcol = mix(col1, col2, fac);\n}\nvoid node_mix_clamp_color(float4 col, float4 min, float4 max, _ref(float4 ,out_col))\n{\n  out_col = clamp(col, min, max);\n}\nvoid node_mix_clamp_vector(float3 vec, float3 min, float3 max, _ref(float3 ,outvec))\n{\n  outvec = clamp(vec, min, max);\n}\nvoid node_mix_clamp_value(float value, float min, float max, _ref(float ,outfloat))\n{\n  outfloat = clamp(value, min, max);\n}\nvoid node_mix_rotation(float fac, float4 rot1, float4 rot2, _ref(float4 ,outrot))\n{\n  outrot = _as_float4(interpolate(_ctor(Quaternion) UNPACK4(rot1) _rotc() , _ctor(Quaternion) UNPACK4(rot2) _rotc() , fac));\n}"
