  "code": "float2 calc_brick_texture(float3 p,\n                          float mortar_size,\n                          float mortar_smooth,\n                          float bias,\n                          float brick_width,\n                          float row_height,\n                          float offset_amount,\n                          int offset_frequency,\n                          float squash_amount,\n                          int squash_frequency)\n{\n  int bricknum, rownum;\n  float offset = 0.0f;\n  float x, y;\n\n  rownum = int(floor(p.y / row_height));\n\n  if (offset_frequency != 0 && squash_frequency != 0) {\n    brick_width *= (rownum % squash_frequency != 0) ? 1.0f : squash_amount;\n    offset = (rownum % offset_frequency != 0) ? 0.0f : (brick_width * offset_amount);\n  }\n\n  bricknum = int(floor((p.x + offset) / brick_width));\n\n  x = (p.x + offset) - brick_width * float(bricknum);\n  y = p.y - row_height * float(rownum);\n\n  float tint = clamp((integer_noise((rownum << 16) + (bricknum & 0xFFFF)) + bias), 0.0f, 1.0f);\n\n  float min_dist = min(min(x, y), min(brick_width - x, row_height - y));\n  if (min_dist >= mortar_size) {\n    return float2(tint, 0.0f);\n  }\n  else if (mortar_smooth == 0.0f) {\n    return float2(tint, 1.0f);\n  }\n  else {\n    min_dist = 1.0f - min_dist / mortar_size;\n    return float2(tint, smoothstep(0.0f, mortar_smooth, min_dist));\n  }\n}\nvoid node_tex_brick(float3 co,\n                    float4 color1,\n                    float4 color2,\n                    float4 mortar,\n                    float scale,\n                    float mortar_size,\n                    float mortar_smooth,\n                    float bias,\n                    float brick_width,\n                    float row_height,\n                    float offset_amount,\n                    float offset_frequency,\n                    float squash_amount,\n                    float squash_frequency,\n                    _ref(float4 ,color),\n                    _ref(float ,fac))\n{\n  float2 f2 = calc_brick_texture(co * scale,\n                                 mortar_size,\n                                 mortar_smooth,\n                                 bias,\n                                 brick_width,\n                                 row_height,\n                                 offset_amount,\n                                 int(offset_frequency),\n                                 squash_amount,\n                                 int(squash_frequency));\n  float tint = f2.x;\n  float f = f2.y;\n  if (f != 1.0f) {\n    float facm = 1.0f - tint;\n    color1 = facm * color1 + tint * color2;\n  }\n  color = mix(color1, mortar, f);\n  fac = f;\n}"
