  "code": "float calc_gradient(float3 p, int gradient_type)\n{\n  float x, y, z;\n  x = p.x;\n  y = p.y;\n  z = p.z;\n  if (gradient_type == 0) {\n    return x;\n  }\n  else if (gradient_type == 1) {\n    float r = max(x, 0.0f);\n    return r * r;\n  }\n  else if (gradient_type == 2) {\n    float r = min(max(x, 0.0f), 1.0f);\n    float t = r * r;\n    return (3.0f * t - 2.0f * t * r);\n  }\n  else if (gradient_type == 3) {\n    return (x + y) * 0.5f;\n  }\n  else if (gradient_type == 4) {\n    return atan(y, x) / (M_PI * 2.0f) + 0.5f;\n  }\n  else {\n    float r = max(0.999999f - sqrt(x * x + y * y + z * z), 0.0f);\n    if (gradient_type == 5) {\n      return r * r;\n    }\n    else if (gradient_type == 6) {\n      return r;\n    }\n  }\n  return 0.0f;\n}\nvoid node_tex_gradient(float3 co, float gradient_type, _ref(float4 ,color), _ref(float ,fac))\n{\n  float f = calc_gradient(co, int(gradient_type));\n  f = clamp(f, 0.0f, 1.0f);\n\n  color = float4(f, f, f, 1.0f);\n  fac = f;\n}"
