 "gpu_shader_material_fractal_noise.glsl": {
  "deps": [
   "gpu_shader_math_constants_lib.glsl",
   "gpu_shader_common_hash.glsl",
   "gpu_shader_material_noise.glsl"
  ],
  "code": "#define NOISE_FBM(T) \\\n  float noise_fbm(T co, \\\n                  float detail, \\\n                  float roughness, \\\n                  float lacunarity, \\\n                  float offset, \\\n                  float gain, \\\n                  bool normalize) \\\n  { \\\n    T p = co; \\\n    float fscale = 1.0f; \\\n    float amp = 1.0f; \\\n    float maxamp = 0.0f; \\\n    float sum = 0.0f; \\\n    for (int i = 0; i <= int(detail); i++) { \\\n      float t = snoise(fscale * p); \\\n      sum += t * amp; \\\n      maxamp += amp; \\\n      amp *= roughness; \\\n      fscale *= lacunarity; \\\n    } \\\n    float rmd = detail - floor(detail); \\\n    if (rmd != 0.0f) { \\\n      float t = snoise(fscale * p); \\\n      float sum2 = sum + t * amp; \\\n      return normalize ? \\\n                 mix(0.5f * sum / maxamp + 0.5f, 0.5f * sum2 / (maxamp + amp) + 0.5f, rmd) : \\\n                 mix(sum, sum2, rmd); \\\n    } \\\n    else { \\\n      return normalize ? 0.5f * sum / maxamp + 0.5f : sum; \\\n    } \\\n  }\n\n#define NOISE_MULTI_FRACTAL(T) \\\n  float noise_multi_fractal(T co, \\\n                            float detail, \\\n                            float roughness, \\\n                            float lacunarity, \\\n                            float offset, \\\n                            float gain, \\\n                            bool normalize) \\\n  { \\\n    T p = co; \\\n    float value = 1.0f; \\\n    float pwr = 1.0f; \\\n    for (int i = 0; i <= int(detail); i++) { \\\n      value *= (pwr * snoise(p) + 1.0f); \\\n      pwr *= roughness; \\\n      p *= lacunarity; \\\n    } \\\n    float rmd = detail - floor(detail); \\\n    if (rmd != 0.0f) { \\\n      value *= (rmd * pwr * snoise(p) + 1.0f);                \\\n    } \\\n    return value; \\\n  }\n\n#define NOISE_HETERO_TERRAIN(T) \\\n  float noise_hetero_terrain(T co, \\\n                             float detail, \\\n                             float roughness, \\\n                             float lacunarity, \\\n                             float offset, \\\n                             float gain, \\\n                             bool normalize) \\\n  { \\\n    T p = co; \\\n    float pwr = roughness; \\\n    float value = offset + snoise(p); \\\n    p *= lacunarity; \\\n    for (int i = 1; i <= int(detail); i++) { \\\n      float increment = (snoise(p) + offset) * pwr * value; \\\n      value += increment; \\\n      pwr *= roughness; \\\n      p *= lacunarity; \\\n    } \\\n    float rmd = detail - floor(detail); \\\n    if (rmd != 0.0f) { \\\n      float increment = (snoise(p) + offset) * pwr * value; \\\n      value += rmd * increment; \\\n    } \\\n    return value; \\\n  }\n\n#define NOISE_HYBRID_MULTI_FRACTAL(T) \\\n  float noise_hybrid_multi_fractal(T co, \\\n                                   float detail, \\\n                                   float roughness, \\\n                                   float lacunarity, \\\n                                   float offset, \\\n                                   float gain, \\\n                                   bool normalize) \\\n  { \\\n    T p = co; \\\n    float pwr = 1.0f; \\\n    float value = 0.0f; \\\n    float weight = 1.0f; \\\n    for (int i = 0; (weight > 0.001f) && (i <= int(detail)); i++) { \\\n      if (weight > 1.0f) { \\\n        weight = 1.0f; \\\n      } \\\n      float signal = (snoise(p) + offset) * pwr; \\\n      pwr *= roughness; \\\n      value += weight * signal; \\\n      weight *= gain * signal; \\\n      p *= lacunarity; \\\n    } \\\n    float rmd = detail - floor(detail); \\\n    if ((rmd != 0.0f) && (weight > 0.001f)) { \\\n      if (weight > 1.0f) { \\\n        weight = 1.0f; \\\n      } \\\n      float signal = (snoise(p) + offset) * pwr; \\\n      value += rmd * weight * signal; \\\n    } \\\n    return value; \\\n  }\n\n#define NOISE_RIDGED_MULTI_FRACTAL(T) \\\n  float noise_ridged_multi_fractal(T co, \\\n                                   float detail, \\\n                                   float roughness, \\\n                                   float lacunarity, \\\n                                   float offset, \\\n                                   float gain, \\\n                                   bool normalize) \\\n  { \\\n    T p = co; \\\n    float pwr = roughness; \\\n    float signal = offset - abs(snoise(p)); \\\n    signal *= signal; \\\n    float value = signal; \\\n    float weight = 1.0f; \\\n    for (int i = 1; i <= int(detail); i++) { \\\n      p *= lacunarity; \\\n      weight = clamp(signal * gain, 0.0f, 1.0f); \\\n      signal = offset - abs(snoise(p)); \\\n      signal *= signal; \\\n      signal *= weight; \\\n      value += signal * pwr; \\\n      pwr *= roughness; \\\n    } \\\n    return value; \\\n  }\nNOISE_FBM(float)\nNOISE_FBM(float2)\nNOISE_FBM(float3)\nNOISE_FBM(float4)\nNOISE_MULTI_FRACTAL(float)\nNOISE_MULTI_FRACTAL(float2)\nNOISE_MULTI_FRACTAL(float3)\nNOISE_MULTI_FRACTAL(float4)\nNOISE_HETERO_TERRAIN(float)\nNOISE_HETERO_TERRAIN(float2)\nNOISE_HETERO_TERRAIN(float3)\nNOISE_HETERO_TERRAIN(float4)\nNOISE_HYBRID_MULTI_FRACTAL(float)\nNOISE_HYBRID_MULTI_FRACTAL(float2)\nNOISE_HYBRID_MULTI_FRACTAL(float3)\nNOISE_HYBRID_MULTI_FRACTAL(float4)\nNOISE_RIDGED_MULTI_FRACTAL(float)\nNOISE_RIDGED_MULTI_FRACTAL(float2)\nNOISE_RIDGED_MULTI_FRACTAL(float3)\nNOISE_RIDGED_MULTI_FRACTAL(float4)"
 },
