  "code": "float calc_wave(float3 p,\n                float distortion,\n                float detail,\n                float detail_scale,\n                float detail_roughness,\n                float phase,\n                int wave_type,\n                int bands_dir,\n                int rings_dir,\n                int wave_profile)\n{\n\n  p = (p + 0.000001f) * 0.999999f;\n\n  float n;\n\n  if (wave_type == 0) {\n    if (bands_dir == 0) {\n      n = p.x * 20.0f;\n    }\n    else if (bands_dir == 1) {\n      n = p.y * 20.0f;\n    }\n    else if (bands_dir == 2) {\n      n = p.z * 20.0f;\n    }\n    else {\n      n = (p.x + p.y + p.z) * 10.0f;\n    }\n  }\n  else {\n    float3 rp = p;\n    if (rings_dir == 0) {\n      rp *= float3(0.0f, 1.0f, 1.0f);\n    }\n    else if (rings_dir == 1) {\n      rp *= float3(1.0f, 0.0f, 1.0f);\n    }\n    else if (rings_dir == 2) {\n      rp *= float3(1.0f, 1.0f, 0.0f);\n    }\n    n = length(rp) * 20.0f;\n  }\n\n  n += phase;\n\n  if (distortion != 0.0f) {\n    n += distortion *\n         (noise_fbm(p * detail_scale, detail, detail_roughness, 2.0f, 0.0f, 0.0f, true) * 2.0f -\n          1.0f);\n  }\n\n  if (wave_profile == 0) {\n    return 0.5f + 0.5f * sin(n - M_PI_2);\n  }\n  else if (wave_profile == 1) {\n    n /= 2.0f * M_PI;\n    return n - floor(n);\n  }\n  else {\n    n /= 2.0f * M_PI;\n    return abs(n - floor(n + 0.5f)) * 2.0f;\n  }\n}\nvoid node_tex_wave(float3 co,\n                   float scale,\n                   float distortion,\n                   float detail,\n                   float detail_scale,\n                   float detail_roughness,\n                   float phase,\n                   float wave_type,\n                   float bands_dir,\n                   float rings_dir,\n                   float wave_profile,\n                   _ref(float4 ,color),\n                   _ref(float ,fac))\n{\n  float f;\n  f = calc_wave(co * scale,\n                distortion,\n                detail,\n                detail_scale,\n                detail_roughness,\n                phase,\n                int(wave_type),\n                int(bands_dir),\n                int(rings_dir),\n                int(wave_profile));\n\n  color = float4(f, f, f, 1.0f);\n  fac = f;\n}"
