  "code": "void node_attribute_color(float4 attr, _ref(float4 ,out_attr))\n{\n  out_attr = attr_load_color_post(attr);\n}\nvoid node_attribute_temperature(float4 attr, _ref(float4 ,out_attr))\n{\n  float temperature = attr_load_temperature_post(attr.x);\n  out_attr.x = temperature;\n  out_attr.y = temperature;\n  out_attr.z = temperature;\n  out_attr.w = 1.0f;\n}\nvoid node_attribute_density(float4 attr, _ref(float ,out_attr))\n{\n  out_attr = attr.x;\n}\nvoid node_attribute_flame(float4 attr, _ref(float ,out_attr))\n{\n  out_attr = attr.x;\n}\nvoid node_attribute_uniform(float4 attr, const float attr_hash, _ref(float4 ,out_attr))\n{\n  out_attr = attr_load_uniform(attr, floatBitsToUint(attr_hash));\n}\n\nfloat4 attr_load_layer(const uint attr_hash)\n{\n#ifdef VLATTR_LIB\n\n  uint left = 0, right = drw_layer_attrs[0].buffer_length;\n\n  while (left < right) {\n    uint mid = (left + right) / 2;\n    uint hash = drw_layer_attrs[mid].hash_code;\n\n    if (hash < attr_hash) {\n      left = mid + 1;\n    }\n    else if (hash > attr_hash) {\n      right = mid;\n    }\n    else {\n      return drw_layer_attrs[mid].data;\n    }\n  }\n#endif\n\n  return float4(0.0f);\n}\nvoid node_attribute(float4 attr, _ref(float4 ,outcol), _ref(float3 ,outvec), _ref(float ,outf), _ref(float ,outalpha))\n{\n  outcol = float4(attr.xyz, 1.0f);\n  outvec = attr.xyz;\n  outf = math_average(attr.xyz);\n  outalpha = attr.w;\n}"
